/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

s32 startAudioStream(s32, M2C_UNK, M2C_UNK, s32, s32, s32, s32); /* extern */
M2C_UNK processDataBankById(s32);                         /* extern */
s32 isSlotActiveById(s32);                             /* extern */
extern s32 gMusicStreamId;
extern u8 gOptionFlag;

/* Stops the current music stream if active and starts a new one; returns -1 if audio option is off. */ s32 playMusicStream(s32 streamId, s32 volume) {
    s32 newStream;

    if (gOptionFlag == 0) {
        return -1;
    }
    if (gMusicStreamId != -1) {
        if (isSlotActiveById(gMusicStreamId) & 0xFF) {
            processDataBankById(gMusicStreamId);
        }
    }
    newStream = startAudioStream(streamId, 0x2EE0, 0xFF, volume & 0xFF, 0x40, 0, 0);
    gMusicStreamId = newStream;
    return newStream;
}
